//---------------------------------------------------------------------
// Main function
//---------------------------------------------------------------------
int main(void) {
    volatile int *pixel_ctrl_ptr = (int *)0xFF203020;
    pixel_buffer_start = *pixel_ctrl_ptr;
    clear_screen();
 // Create and initialize a stock.
    Stock stock1;
    stock1.dates = global_date;
    stock1.values = apple_price;
    stock1.size = SIZE;
    stock1.name = "apple";
	stock1.color = 0xF800;
    init_stock(&stock1);  // Precompute parsed dates

	    // Create and initialize a stock.
    Stock stock2;
    stock2.dates = global_date;
    stock2.values = meta_price;
    stock2.size = SIZE;
    stock2.name = "meta";
	stock2.color = 0x07E0;
    init_stock(&stock2);  // Precompute parsed dates

	volatile int *KEY_ptr = 0xFF200050;
	// edge capture reg is offset  3 words
    volatile int *Key_edgeCapture_ptr= KEY_ptr + 3;
	 
	 
	 //cheack key inputs
	 while(1){
		 
	 // read the bit, same as lw (derefence pointer)
     int edge_capture = *Key_edgeCapture_ptr;
		 
	 if(edge_capture & 0x1){
		 
		draw_stock(&stock1);
	    draw_stock(&stock2);
		 // clear edgecap for KEY0
         *Key_edgeCapture_ptr= 0x1;
		 
	 }
	 	 
 }
  
    draw_stock(&stock1);
	draw_stock(&stock2);
    free(stock1.parsed_dates);
    return 0;
}

//---------------------------------------------------------------------
// Function implementations
//---------------------------------------------------------------------

// Parse a date string in "M/D/YYYY" format into a time_t.
time_t parse_date(const char *date_str) {
    struct tm t = {0};
    int month, day, year;
    if (sscanf(date_str, "%d/%d/%d", &month, &day, &year) != 3) {
        fprintf(stderr, "Error parsing date: %s\n", date_str);
        exit(EXIT_FAILURE);
    }
    t.tm_mon  = month - 1;  // tm_mon is 0-based
    t.tm_mday = day;
    t.tm_year = year - 1900; // tm_year is years since 1900
    t.tm_hour = 0;
    t.tm_min  = 0;
    t.tm_sec  = 0;
    return mktime(&t);
}

// Initialize the stock by precomputing the parsed dates.
void init_stock(Stock *s) {
    s->parsed_dates = malloc(s->size * sizeof(time_t));
    if (!s->parsed_dates) {
        fprintf(stderr, "Failed to allocate memory for parsed dates.\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < s->size; i++) {
        s->parsed_dates[i] = parse_date(s->dates[i]);
    }
}

// Filter stock data indices that fall within the given year range.
// Returns the number of indices stored in filter_indices.
int filter_data(Stock *s, int *filter_indices, int start_year, int yr_range) {
    int count = 0;
    for (int i = 0; i < s->size; i++) {
        struct tm *tm_ptr = localtime(&s->parsed_dates[i]);
        int year = tm_ptr->tm_year + 1900;
        if (year >= start_year && year < start_year + yr_range) {
            filter_indices[count++] = i;
        }
    }
    return count;
}

// Build a sample list (from filtered indices) based on the chosen sample mode.
// Returns the number of sample indices found.
int sample_data(Stock *s, int *sample_indices, int *filter_indices, int filter_count, int sample_mode) {
    int count = 0;
    if (sample_mode == 0) { // Day mode: every point.
        for (int i = 0; i < filter_count; i++) {
            sample_indices[count++] = filter_indices[i];
        }
    } else if (sample_mode == 1) { // Week mode: use continuous week index relative to first filtered date.
        time_t base_time = s->parsed_dates[filter_indices[0]];
        int last_week = -1;
        for (int i = 0; i < filter_count; i++) {
            double days_since = difftime(s->parsed_dates[filter_indices[i]], base_time) / (60 * 60 * 24);
            int week = (int)(days_since / 7);
            if (week != last_week) {
                if (i > 0)
                    sample_indices[count++] = filter_indices[i - 1];
                last_week = week;
            }
        }
        sample_indices[count++] = filter_indices[filter_count - 1];
    } else if (sample_mode == 2) { // Month mode: use continuous month (year*12+month).
        int last_month = -1;
        for (int i = 0; i < filter_count; i++) {
            struct tm *tm_ptr = localtime(&s->parsed_dates[filter_indices[i]]);
            int continuous_month = (tm_ptr->tm_year * 12) + tm_ptr->tm_mon;
            if (continuous_month != last_month) {
                if (i > 0)
                    sample_indices[count++] = filter_indices[i - 1];
                last_month = continuous_month;
            }
        }
        sample_indices[count++] = filter_indices[filter_count - 1];
    }
    return count;
}

// Select the first 'window_size' sample indices (or all if fewer available).
int select_window(int *window_indices, int *sample_indices, int sample_count, int window_size) {
    int count = (sample_count < window_size) ? sample_count : window_size;
    for (int i = 0; i < count; i++) {
        window_indices[i] = sample_indices[i];
    }
    return count;
}

// Compute the minimum and maximum stock values among the selected samples.
void compute_sample_min_max(Stock *s, int *sample_indices, int count, float *min, float *max) {
    *min = s->values[sample_indices[0]];
    *max = s->values[sample_indices[0]];
    for (int i = 0; i < count; i++) {
        int idx = sample_indices[i];
        if (s->values[idx] < *min)
            *min = s->values[idx];
        if (s->values[idx] > *max)
            *max = s->values[idx];
    }
}

// Normalize the stock values (for the selected samples) to the graph's vertical range.
void normalize_samples(Stock *s, int *sample_indices, int count, float sample_min, float sample_max, int *normalized) {
    for (int i = 0; i < count; i++) {
        int idx = sample_indices[i];
        int norm_val = (int)(((s->values[idx] - sample_min) / (sample_max - sample_min)) * GRAPH_HEIGHT);
        normalized[i] = (SCREEN_HEIGHT - GRAPH_HEIGHT_PADDING) - norm_val;
    }
}

// Draw the graph by connecting the normalized points.
void draw_graph(int *normalized, int count, short int color) {
    //drawing axis
	draw_line(40, 220, 320, 220, 0xFFFF); // x-axis
	draw_line(40, 220, 40, 20, 0xFFFF); // y-axis


    // Calculate and display y-axis labels
    int y_divisions[5];
    calculate_y_divisions(apple_price, SIZE, y_divisions);

    for (int j = 0; j < count - 1; j++) {
        int x0 = GRAPH_WIDTH_PADDING + j;
        int x1 = GRAPH_WIDTH_PADDING + j + 1;
        int y0 = normalized[j];
        int y1 = normalized[j + 1];
        draw_line(x0, y0, x1, y1, color);
    }
}

void calculate_y_divisions(float arr[], int size, float divisions[]) {

    char buffer[20];
    char buffer1[20];
    char buffer2[20];
    char buffer3[20];
    char buffer4[20];
    // Find min and max values
    float min_val = arr[0];
    float max_val = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] < min_val) min_val = arr[i];
        if (arr[i] > max_val) max_val = arr[i];
    }


//print_string(20, 20, "done part2");
    // Calculate division intervals
    float step = (max_val - min_val) / 4; // 5 divisions, 4 gaps
    for (int i = 0; i < 5; i++) {
        divisions[i] = min_val + i * step;
    }

snprintf(buffer, sizeof(buffer), "%.2f", divisions[0]);
snprintf(buffer1, sizeof(buffer1), "%.2f", divisions[1]);
snprintf(buffer2, sizeof(buffer2), "%.2f", divisions[2]);
snprintf(buffer3, sizeof(buffer3), "%.2f", divisions[3]);
snprintf(buffer4, sizeof(buffer4), "%.2f", divisions[4]);


print_string(4, map_vga_y_to_char_y(20), buffer4);  
print_string(4, map_vga_y_to_char_y(70), buffer3);
print_string(4, map_vga_y_to_char_y(120), buffer2);
print_string(4, map_vga_y_to_char_y(170), buffer1); 
print_string(4, map_vga_y_to_char_y(219), buffer);  

}

int map_vga_y_to_char_y(int vga_y) {
    if (vga_y < 0) vga_y = 0;  // Clamp to min
    if (vga_y > 239) vga_y = 239;  // Clamp to max
    return (vga_y * 60) / 240;  // Scale VGA Y to Character Buffer Y
}

// Function to write a character to the character buffer at (x, y)
void write_char(int x, int y, char c) {
    if (x < 0 || x >= 80 || y < 0 || y >= 60) return; // Prevent out-of-bounds access
    
	volatile char *char_buffer = (volatile char *)CHAR_BUFFER_BASE;
    char_buffer += (y * 128) + x;  // Corrected address calculation
    *char_buffer = c;  // Write character to memory-mapped VGA buffer
}

// Function to print a string at a specific location
void print_string(int x, int y, const char *str) {
    while (*str) {
        write_char(x++, y, *str++);	
    }
}
	

// Draw a stock: filter, sample, select a window, normalize, and draw.
void draw_stock(Stock *s) {
    int filter_indices[SIZE];
    int filter_count = filter_data(s, filter_indices, SELECTED_YEAR_START, YEAR_RANGE);
    if (filter_count == 0) {
        printf("No data from year %d to %d.\n", SELECTED_YEAR_START, SELECTED_YEAR_START + YEAR_RANGE - 1);
        return;
    }

    int sample_indices[SIZE];
    int sample_count = sample_data(s, sample_indices, filter_indices, filter_count, SAMPLE_MODE);
    printf("Temp sample count = %d\n", sample_count);
    printf("Displaying from %s to %s\n",
           s->dates[sample_indices[0]],
           s->dates[sample_indices[sample_count - 1]]);

    int window_indices[GRAPH_WIDTH];
    int window_count = select_window(window_indices, sample_indices, sample_count, GRAPH_WIDTH);
    printf("Window sample count = %d\n", window_count);
    printf("Displaying from %s to %s\n",
           s->dates[window_indices[0]],
           s->dates[window_indices[window_count - 1]]);

    float sample_min, sample_max;
    compute_sample_min_max(s, window_indices, window_count, &sample_min, &sample_max);

    int normalized[GRAPH_WIDTH];
    normalize_samples(s, window_indices, window_count, sample_min, sample_max, normalized);

    draw_graph(normalized, window_count, s->color);
}

// Plot a single pixel at (x,y) with the given color.
void plot_pixel(int x, int y, short int line_color) {
    volatile short int *one_pixel_address = (volatile short int *)(pixel_buffer_start + (y << 10) + (x << 1));
    *one_pixel_address = line_color;
}

// Draw a line from (x0,y0) to (x1,y1) using Bresenham's algorithm.
void draw_line(int x0, int y0, int x1, int y1, short int line_color) {
    bool is_steep = abs(y1 - y0) > abs(x1 - x0);
    if (is_steep) {
        swap(&x0, &y0);
        swap(&x1, &y1);
    }
    if (x0 > x1) {
        swap(&x0, &x1);
        swap(&y0, &y1);
    }
    int deltax = x1 - x0;
    int deltay = abs(y1 - y0);
    int error = -(deltax / 2);
    int y = y0;
    int y_step = (y0 < y1) ? 1 : -1;
    for (int x = x0; x < x1; x++) {
        if (is_steep)
            plot_pixel(y, x, line_color);
        else
            plot_pixel(x, y, line_color);
        error += deltay;
        if (error > 0) {
            y += y_step;
            error -= deltax;
        }
    }
}

// Swap two integers.
void swap(int* x, int* y) {
    int temp = *x;
    *x = *y;
    *y = temp;
}

// Clear the entire screen.
void clear_screen(void) {
    volatile char *char_buffer = (volatile char *)CHAR_BUFFER_BASE;

    // Loop through all 80x60 positions and write a blank space (ASCII 32)
    for (int y = 0; y < 60; y++) {
        for (int x = 0; x < 80; x++) {
            char_buffer[(y * 128) + x] = ' ';  // Write a space to clear
        }
    }

    for (int x = 0; x < SCREEN_WIDTH; x++)
        for (int y = 0; y < SCREEN_HEIGHT; y++)
            plot_pixel(x, y, 0);
}
